<?php
namespace Tests\Feature;
use App\Models\User;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class ExamResultsTest extends TestCase {
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test DB required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-18 07:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();parent::tearDown();}
 private function fixture(string $code='A',string $role='owner'):array {
  if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Exam '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$campus=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$user=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$user->id,'status'=>'active']);$rid=DB::table('roles')->where('name',$role)->value('id');DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>$rid]);DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$mid,'campus_id'=>$campus]);$session=DB::table('academic_sessions')->insertGetId(['school_id'=>$sid,'name'=>'2026-27','starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','status'=>'active']);$class=DB::table('classes')->insertGetId(['school_id'=>$sid,'name'=>'Class 1','position'=>1]);$section=DB::table('sections')->insertGetId(['school_id'=>$sid,'campus_id'=>$campus,'academic_session_id'=>$session,'class_id'=>$class,'name'=>'A']);$math=DB::table('subjects')->insertGetId(['school_id'=>$sid,'name'=>'Math','code'=>'MATH']);$eng=DB::table('subjects')->insertGetId(['school_id'=>$sid,'name'=>'English','code'=>'ENG']);foreach([$math,$eng] as $subject)DB::table('section_subjects')->insert(['school_id'=>$sid,'section_id'=>$section,'subject_id'=>$subject,'required_for_diary'=>true]);$scheme=DB::table('grading_schemes')->insertGetId(['school_id'=>$sid,'name'=>'School standard','version'=>1,'rules'=>json_encode(['passing_percent'=>'40','bands'=>[['label'=>'A','min_percent'=>'80'],['label'=>'B','min_percent'=>'70'],['label'=>'C','min_percent'=>'40'],['label'=>'F','min_percent'=>'0']]]),'rounding_policy'=>'two_decimals','tie_policy'=>'competition']);$students=[];$enrollments=[];for($i=1;$i<=2;$i++){$students[]= $st=DB::table('students')->insertGetId(['school_id'=>$sid,'admission_no'=>'EX-'.$i,'first_name'=>$i===1?'Ali':'Sara','admitted_on'=>'2026-10-01','status'=>'active']);$enrollments[]=DB::table('enrollments')->insertGetId(['school_id'=>$sid,'student_id'=>$st,'section_id'=>$section,'starts_on'=>'2026-10-01','roll_no'=>(string)$i,'status'=>'active']);}$guardian=DB::table('guardians')->insertGetId(['school_id'=>$sid,'name'=>'Parent One','phone'=>'+923001234567']);DB::table('student_guardians')->insert(['school_id'=>$sid,'student_id'=>$students[0],'guardian_id'=>$guardian,'relationship'=>'father','is_primary'=>true,'can_receive_reports'=>true,'can_pick_up'=>true]);$staff=DB::table('staff_profiles')->insertGetId(['school_id'=>$sid,'membership_id'=>$mid,'employee_no'=>'T1','status'=>'active']);DB::table('teacher_assignments')->insert(['school_id'=>$sid,'staff_profile_id'=>$staff,'section_id'=>$section,'subject_id'=>$math,'is_class_teacher'=>true]);return compact('sid','campus','user','mid','rid','session','class','section','math','eng','scheme','students','enrollments','guardian','staff');
 }
 private function login(array $f):void{$this->actingAs($f['user'])->withSession(['school_id'=>$f['sid']]);}
 private function testData(array $f,int $subject=0,?int $cycle=null,string $type='exam',string $max='100'):array{return ['section_id'=>$f['section'],'subject_id'=>$subject?:$f['math'],'grading_scheme_id'=>$f['scheme'],'exam_cycle_id'=>$cycle,'title'=>'Class assessment','test_date'=>'2026-10-18','max_marks'=>$max,'passing_marks'=>(string)((float)$max*0.4),'assessment_type'=>$type,'lock_version'=>0];}
 private function create(array $f,int $subject=0,?int $cycle=null,string $type='exam',string $max='100'):int{return $this->postJson('/app-api/exams/tests',$this->testData($f,$subject,$cycle,$type,$max))->assertOk()->json('id');}
 private function version(int $test):int{return (int)DB::table('tests')->where('id',$test)->value('lock_version');}
 private function rows(array $f,string $first='80',string $second='0',string $secondStatus='present'):array{return [['enrollment_id'=>$f['enrollments'][0],'status'=>'present','marks'=>$first,'remarks'=>'Checked'],['enrollment_id'=>$f['enrollments'][1],'status'=>$secondStatus,'marks'=>$secondStatus==='present'?$second:null,'remarks'=>null]];}
 private function change(int $id,string $action,array $extra=[]){return $this->postJson('/app-api/exams/tests/'.$id.'/marks',array_merge(['lock_version'=>$this->version($id),'action'=>$action],$extra));}
 private function publish(array $f,int $test,array $rows):void{$this->change($test,'save',['records'=>$rows])->assertOk();$this->change($test,'submit')->assertOk();$this->change($test,'publish')->assertOk();}
 private function report(int $test,int $enrollment):int{return (int)DB::table('report_snapshots as p')->join('test_results as r','r.id','=','p.test_result_id')->where('r.test_id',$test)->where('r.enrollment_id',$enrollment)->orderByDesc('p.revision')->value('p.id');}
 private function cycle(array $f):int{return $this->postJson('/app-api/exams/cycles',['section_id'=>$f['section'],'name'=>'Term exam','starts_on'=>'2026-10-01','ends_on'=>'2026-10-18','grading_scheme_id'=>$f['scheme']])->assertOk()->json('id');}
 private function cycleDetail(array $f,int $cycle){return $this->getJson('/app-api/exams/cycle?exam_cycle_id='.$cycle.'&section_id='.$f['section']);}
 private function consolidate(array $f,int $cycle,?string $reason=null){$data=$this->cycleDetail($f,$cycle)->assertOk()->json();return $this->postJson('/app-api/exams/consolidate',['exam_cycle_id'=>$cycle,'section_id'=>$f['section'],'lock_version'=>$data['cycle']['lock_version'],'source_digest'=>$data['source_digest'],'reason'=>$reason]);}
 public function test_review_publication_preserves_zero_absent_and_frozen_student_report_metadata():void {
  $f=$this->fixture();$this->login($f);$id=$this->create($f);$this->getJson('/app-api/exams/tests/'.$id.'/marks')->assertOk()->assertJsonPath('roster.0.status','pending');$this->publish($f,$id,$this->rows($f,'0','0','absent'));$report=$this->report($id,$f['enrollments'][0]);DB::table('students')->where('id',$f['students'][0])->update(['first_name'=>'Changed']);DB::table('subjects')->where('id',$f['math'])->update(['name'=>'Changed Math']);$this->getJson('/app-api/exams/report?kind=test&id='.$report)->assertOk()->assertJsonPath('payload.student.first_name','Ali')->assertJsonPath('payload.subject_name','Math')->assertJsonPath('payload.marks','0.00')->assertJsonPath('payload.outcome','Fail')->assertJsonPath('payload.grade','F')->assertJsonPath('is_current',true);$absent=$this->report($id,$f['enrollments'][1]);$this->getJson('/app-api/exams/report?kind=test&id='.$absent)->assertJsonPath('payload.status','absent')->assertJsonPath('payload.marks',null)->assertJsonPath('payload.rank',null);$this->change($id,'save',['records'=>$this->rows($f)])->assertUnprocessable();$this->artisan('database:verify')->assertSuccessful();
 }
 public function test_marks_validation_stale_tabs_review_feedback_and_roster_changes_are_safe():void {
  $f=$this->fixture();$this->login($f);$id=$this->create($f);$this->change($id,'submit')->assertUnprocessable();$rows=$this->rows($f,'101');$this->change($id,'save',['records'=>$rows])->assertUnprocessable();$rows=$this->rows($f);$rows[1]['status']='absent';$this->change($id,'save',['records'=>$rows])->assertUnprocessable();$this->change($id,'save',['records'=>[$rows[0]]])->assertUnprocessable();$v=$this->version($id);$this->change($id,'save',['records'=>$this->rows($f)])->assertOk();$this->postJson('/app-api/exams/tests/'.$id.'/marks',['lock_version'=>$v,'action'=>'save','records'=>$this->rows($f,'20')])->assertUnprocessable();$this->change($id,'submit')->assertOk();$this->change($id,'return')->assertUnprocessable();$this->change($id,'return',['reason'=>'Verify one answer again'])->assertOk();DB::table('enrollments')->where('id',$f['enrollments'][1])->update(['ends_on'=>'2026-10-17']);$this->change($id,'save',['records'=>[$this->rows($f)[0]]])->assertUnprocessable();$this->assertDatabaseCount('test_results',2);
 }
 public function test_subject_teacher_scope_and_publication_denials_apply_to_all_actions():void {
  $f=$this->fixture('T','teacher');$other=$this->fixture('B');$this->login($f);$id=$this->create($f);$this->postJson('/app-api/exams/tests',$this->testData($f,$f['eng']))->assertForbidden();$this->postJson('/app-api/exams/tests',$this->testData($other))->assertNotFound();$this->change($id,'save',['records'=>$this->rows($f)])->assertOk();$this->change($id,'submit')->assertOk();$this->change($id,'publish')->assertForbidden();$this->change($id,'return',['reason'=>'Unauthorized return'])->assertForbidden();$this->postJson('/app-api/exams/schemes',['name'=>'Scheme','passing_percent'=>40,'rounding_policy'=>'two_decimals','tie_policy'=>'none','bands'=>[['label'=>'P','min_percent'=>40],['label'=>'F','min_percent'=>0]]])->assertForbidden();DB::table('staff_profiles')->where('id',$f['staff'])->update(['status'=>'inactive']);$this->getJson('/app-api/exams/tests/'.$id.'/marks')->assertNotFound();
 }
 public function test_grading_versions_rounding_and_ties_are_explicit_and_immutable():void {
  $f=$this->fixture();$this->login($f);$d=['name'=>'New scheme','passing_percent'=>'40','rounding_policy'=>'whole_percent','tie_policy'=>'dense','bands'=>[['label'=>'Pass','min_percent'=>'40'],['label'=>'Fail','min_percent'=>'0']]];$id=$this->postJson('/app-api/exams/schemes',$d)->assertOk()->json('id');$this->postJson('/app-api/exams/schemes',$d)->assertOk();$this->assertDatabaseHas('grading_schemes',['name'=>'New scheme','version'=>2]);$d['bands'][1]['min_percent']='1';$this->postJson('/app-api/exams/schemes',$d)->assertUnprocessable();$exam=app(\App\Services\ExamAccess::class);$g=$exam->scheme($f['sid'],$id);$this->assertSame(4000,$exam->percent(395,1000,$g));$this->assertSame('Pass',$exam->grade(4000,$g));$svc=app(\App\Services\SchoolAssessments::class);$this->assertSame([1=>1,2=>1,3=>3],$svc->ranks([1=>80,2=>80,3=>70],'competition'));$this->assertSame([1=>1,2=>1,3=>2],$svc->ranks([1=>80,2=>80,3=>70],'dense'));$this->assertSame([],$svc->ranks([1=>80],'none'));
 }
 public function test_corrections_archive_old_reports_and_require_fresh_guardian_sharing():void {
  $f=$this->fixture();$this->login($f);$id=$this->create($f);$this->publish($f,$id,$this->rows($f));$old=$this->report($id,$f['enrollments'][0]);$share=['kind'=>'test','id'=>$old,'guardian_id'=>$f['guardian'],'recipient_phone'=>'+923001234567','confirmed'=>true];$this->postJson('/app-api/exams/share',$share)->assertOk();$this->postJson('/app-api/exams/share',$share)->assertOk();$this->assertDatabaseCount('report_shares',1);$list=$this->getJson('/app-api/exams/tests/'.$id.'/marks')->assertOk()->json('reports');$this->assertSame(1,collect($list)->firstWhere('id',$old)['shared_count']);$this->change($id,'revise')->assertUnprocessable();$this->change($id,'revise',['reason'=>'Corrected after paper recheck'])->assertOk();$this->postJson('/app-api/exams/share',$share)->assertForbidden();$this->publish($f,$id,$this->rows($f,'90'));$new=$this->report($id,$f['enrollments'][0]);$this->getJson('/app-api/exams/report?kind=test&id='.$old)->assertJsonPath('payload.marks','80.00')->assertJsonPath('is_current',false)->assertJsonCount(1,'shares');$this->getJson('/app-api/exams/report?kind=test&id='.$new)->assertJsonPath('payload.marks','90.00')->assertJsonPath('payload.revision',2)->assertJsonCount(0,'shares');$this->getJson('/app-api/exams/tests/'.$id.'/history')->assertOk()->assertJsonPath('data.0.action','exams.publish');
 }
 public function test_guardian_consent_recipient_phone_changes_and_cross_school_report_access_are_enforced():void {
  $f=$this->fixture();$b=$this->fixture('B');$this->login($f);$id=$this->create($f);$this->publish($f,$id,$this->rows($f));$snapshot=$this->report($id,$f['enrollments'][0]);$d=['kind'=>'test','id'=>$snapshot,'guardian_id'=>$f['guardian'],'recipient_phone'=>'+923001234567','confirmed'=>false];$this->postJson('/app-api/exams/share',$d)->assertUnprocessable();$d['confirmed']=true;$d['guardian_id']=$b['guardian'];$this->postJson('/app-api/exams/share',$d)->assertNotFound();$d['guardian_id']=$f['guardian'];DB::table('guardians')->where('id',$f['guardian'])->update(['whatsapp_phone'=>'+923009876543']);$this->postJson('/app-api/exams/share',$d)->assertUnprocessable();DB::table('student_guardians')->where('guardian_id',$f['guardian'])->update(['can_receive_reports'=>false]);$this->postJson('/app-api/exams/share',$d)->assertNotFound();$this->assertDatabaseCount('report_shares',0);$this->login($b);$this->getJson('/app-api/exams/report?kind=test&id='.$snapshot)->assertNotFound();
 }
 public function test_csv_and_xlsx_import_preview_are_bounded_atomic_and_do_not_save_marks():void {
  $f=$this->fixture();$this->login($f);$id=$this->create($f);$csv="admission_no,status,marks,remarks\nEX-1,present,0,Zero is valid\nEX-2,absent,,Sick\n";$this->post('/app-api/exams/tests/'.$id.'/import',['lock_version'=>0,'file'=>UploadedFile::fake()->createWithContent('marks.csv',$csv)],['Accept'=>'application/json'])->assertOk()->assertJsonPath('rows.0.marks','0')->assertJsonPath('rows.1.status','absent');$this->assertDatabaseCount('test_results',0);$bad=str_replace('EX-2,absent,,Sick','UNKNOWN,present,101,Wrong',$csv);$this->post('/app-api/exams/tests/'.$id.'/import',['lock_version'=>0,'file'=>UploadedFile::fake()->createWithContent('bad.csv',$bad)],['Accept'=>'application/json'])->assertUnprocessable();$path=tempnam(sys_get_temp_dir(),'marks');$z=new \ZipArchive;$z->open($path,\ZipArchive::OVERWRITE);$xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';foreach([['admission_no','status','marks','remarks'],['EX-1','present','75','Workbook']] as $n=>$cells){$xml.='<row r="'.($n+1).'">';foreach($cells as $i=>$v)$xml.='<c r="'.chr(65+$i).($n+1).'" t="inlineStr"><is><t>'.$v.'</t></is></c>';$xml.='</row>';}$xml.='</sheetData></worksheet>';$z->addFromString('xl/worksheets/sheet1.xml',$xml);$z->close();$file=new UploadedFile($path,'marks.xlsx',null,null,true);$this->post('/app-api/exams/tests/'.$id.'/import',['lock_version'=>0,'file'=>$file],['Accept'=>'application/json'])->assertOk()->assertJsonPath('rows.0.marks','75');@unlink($path);$this->assertDatabaseCount('test_results',0);
 }
 public function test_weighted_consolidation_calculates_subject_totals_pass_rules_and_exemptions():void {
  $f=$this->fixture();$this->login($f);$cycle=$this->cycle($f);$quiz=$this->create($f,$f['math'],$cycle,'quiz','20');$math=$this->create($f,$f['math'],$cycle,'exam','80');$eng=$this->create($f,$f['eng'],$cycle);$this->publish($f,$quiz,$this->rows($f,'20','0'));$this->publish($f,$math,$this->rows($f,'40','0','absent'));$this->publish($f,$eng,$this->rows($f,'80','0','exempt'));$this->postJson('/app-api/exams/weights',['section_id'=>$f['section'],'exam_cycle_id'=>$cycle,'subject_id'=>$f['math'],'lock_version'=>0,'weights'=>[['assessment_type'=>'quiz','weight'=>'20'],['assessment_type'=>'exam','weight'=>'80']]])->assertOk();$this->consolidate($f,$cycle)->assertOk()->assertJsonPath('revision',1);$id=DB::table('consolidated_result_snapshots')->where('enrollment_id',$f['enrollments'][0])->value('id');$this->getJson('/app-api/exams/report?kind=cycle&id='.$id)->assertOk()->assertJsonPath('payload.percent','70.00')->assertJsonPath('payload.grade','B')->assertJsonPath('payload.outcome','Pass')->assertJsonPath('payload.rank',1)->assertJsonPath('is_current',true);$id2=DB::table('consolidated_result_snapshots')->where('enrollment_id',$f['enrollments'][1])->value('id');$this->getJson('/app-api/exams/report?kind=cycle&id='.$id2)->assertJsonPath('payload.percent','0.00')->assertJsonPath('payload.outcome','Fail')->assertJsonPath('payload.rank',null);$this->assertDatabaseCount('exam_candidates',2);$this->consolidate($f,$cycle)->assertUnprocessable();$this->consolidate($f,$cycle,'Reviewed term result correction')->assertOk()->assertJsonPath('revision',2);
 }
 public function test_missing_weighted_papers_and_pending_results_block_cards_and_published_weightages_freeze():void {
  $f=$this->fixture();$this->login($f);$cycle=$this->cycle($f);$math=$this->create($f,$f['math'],$cycle);$this->consolidate($f,$cycle)->assertUnprocessable();$this->publish($f,$math,$this->rows($f));$this->consolidate($f,$cycle)->assertUnprocessable();$eng=$this->create($f,$f['eng'],$cycle);$this->publish($f,$eng,$this->rows($f));$weights=['section_id'=>$f['section'],'exam_cycle_id'=>$cycle,'subject_id'=>$f['math'],'lock_version'=>0,'weights'=>[['assessment_type'=>'exam','weight'=>'99']]];$this->postJson('/app-api/exams/weights',$weights)->assertUnprocessable();$this->consolidate($f,$cycle)->assertOk();$weights['lock_version']=1;$weights['weights'][0]['weight']='100';$this->postJson('/app-api/exams/weights',$weights)->assertUnprocessable();$this->change($math,'revise',['reason'=>'Paper correction invalidates cards'])->assertOk();$snapshot=DB::table('consolidated_result_snapshots')->value('id');$this->getJson('/app-api/exams/report?kind=cycle&id='.$snapshot)->assertJsonPath('is_current',false)->assertJsonPath('can_share',false);$this->postJson('/app-api/exams/tests',$this->testData($f,$f['math'],$cycle))->assertUnprocessable();
 }
 public function test_paper_schedule_conflicts_warn_and_candidate_rolls_are_stable():void {
  $f=$this->fixture();$this->login($f);$cycle=$this->cycle($f);$d=$this->testData($f,$f['math'],$cycle);$d['paper']=['starts_at'=>'09:00','ends_at'=>'10:00','room'=>'Room 1'];$this->postJson('/app-api/exams/tests',$d)->assertOk()->assertJsonCount(0,'warnings');$d['subject_id']=$f['eng'];$this->postJson('/app-api/exams/tests',$d)->assertOk()->assertJsonCount(1,'warnings');$this->postJson('/app-api/exams/candidates',['exam_cycle_id'=>$cycle,'section_id'=>$f['section']])->assertOk();$this->postJson('/app-api/exams/candidates',['exam_cycle_id'=>$cycle,'section_id'=>$f['section']])->assertOk();$this->assertDatabaseCount('exam_candidates',2);$candidates=$this->cycleDetail($f,$cycle)->assertJsonCount(2,'candidates')->json('candidates');foreach($candidates as $candidate)$this->assertSame('E'.$candidate['enrollment_id'],$candidate['roll_no']);
 }
 public function test_future_dates_closed_campuses_and_license_permissions_cannot_be_bypassed():void {
  $this->getJson('/app-api/exams/setup')->assertUnauthorized();$f=$this->fixture();$this->login($f);$d=$this->testData($f);$d['test_date']='2026-10-19';$id=$this->postJson('/app-api/exams/tests',$d)->assertOk()->json('id');$this->change($id,'save',['records'=>$this->rows($f)])->assertUnprocessable();DB::table('campuses')->where('id',$f['campus'])->update(['status'=>'inactive']);$this->change($id,'revise',['reason'=>'Cannot edit archive'])->assertUnprocessable();DB::table('campuses')->where('id',$f['campus'])->update(['status'=>'active']);$license=\App\Services\LicenseService::ensure($f['sid']);DB::table('subscriptions')->insert(['school_id'=>$f['sid'],'plan_id'=>DB::table('plans')->value('id'),'license_id'=>$license->id,'kind'=>'paid','student_limit'=>1000,'campus_limit'=>2,'modules'=>json_encode(['tests_results']),'package_name'=>'Results only','starts_on'=>'2026-01-01','ends_on'=>'2027-12-31','price'=>'100','status'=>'active']);$this->getJson('/app-api/exams/setup')->assertOk();DB::table('subscriptions')->update(['modules'=>json_encode(['fees'])]);$this->getJson('/app-api/exams/setup')->assertForbidden();$provider=User::factory()->create();DB::table('platform_admins')->insert(['user_id'=>$provider->id,'active'=>true]);$this->actingAs($provider)->withSession(['school_id'=>$f['sid']])->getJson('/app-api/exams/setup')->assertForbidden();
 }
 public function test_read_only_role_and_campus_boundaries_do_not_gain_write_access_from_upgrade():void {
  $f=$this->fixture('R','teacher');$this->login($f);$id=$this->create($f);$pid=DB::table('permissions')->where('name','tests.enter_marks')->value('id');DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$f['rid'],'permission_id'=>$pid,'enabled'=>false]);$this->seed(\Database\Seeders\ExamAccessSeeder::class);$this->getJson('/app-api/exams/setup')->assertForbidden();DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$f['rid'],'permission_id'=>DB::table('permissions')->where('name','tests.view')->value('id'),'enabled'=>true]);$this->getJson('/app-api/exams/tests/'.$id.'/marks')->assertOk()->assertJsonPath('can_write',false);$this->change($id,'save',['records'=>$this->rows($f)])->assertForbidden();DB::table('membership_campuses')->where('membership_id',$f['mid'])->delete();$this->getJson('/app-api/exams/tests/'.$id.'/marks')->assertNotFound();
 }
